import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.DYd_c05j.js";const u=JSON.parse('{"title":"Notification Engine","description":"","frontmatter":{},"headers":[],"relativePath":"notifications.md","filePath":"notifications.md","lastUpdated":null}'),t={name:"notifications.md"};function r(o,e,l,d,c,p){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="notification-engine" tabindex="-1">Notification Engine <a class="header-anchor" href="#notification-engine" aria-label="Permalink to &quot;Notification Engine&quot;">​</a></h1><p>Homelab Console owns operational notification policy. Producers (watchers, REST, Telegram and MCP agents) record canonical findings and task transitions; they never deliver Telegram messages directly.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>finding or task event -&gt; policy -&gt; persistent outbox -&gt; Telegram delivery</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="policy" tabindex="-1">Policy <a class="header-anchor" href="#policy" aria-label="Permalink to &quot;Policy&quot;">​</a></h2><ul><li>Local critical findings (UPS, thermal, SMART and expired TLS) are available for immediate delivery. Infrastructure critical findings use a short debounce so transient outages can clear before Telegram delivery.</li><li>Warning-level watcher incidents wait for the configured debounce period. If the incident clears or its task reaches a final state before delivery, the outbox row is cancelled.</li><li>Successfully delivered fingerprints enter severity-specific cooldown. Repeated events remain auditable as <code>suppressed</code> rows.</li><li>Connectivity incidents from different watchers are grouped by their shared dependency-graph root during a bounded aggregation window. Canonical incidents and tasks remain separate; only the Telegram presentation is aggregated.</li><li>Aggregate <code>lab.alerts</code> findings join topology groups only for provider-health failures; application errors and intentionally stopped guests remain separate. If a critical incident joins a pending warning group, the delivery deadline is shortened to the critical debounce instead of retaining the warning delay.</li><li>Before delivery the worker rechecks every grouped incident and omits resolved symptoms. When the complete group later clears, the original Telegram message is edited to show that it resolved automatically.</li><li>Fingerprints are deterministic and versioned (<code>v1:...</code>). Models may classify semantic duplicates but never define canonical fingerprints.</li><li>Every provider condition has one watcher owner. Dedicated UPS, Kuma, Cloudflare, gateway/WireGuard and ZeroTier watchers are excluded from the aggregate <code>lab.alerts</code> stream, preventing duplicate tasks and deliveries.</li><li>Watcher incidents clear only after three consecutive successful misses by default; this grace period is independent from warning debounce and cooldown.</li></ul><h2 id="delivery-guarantees" tabindex="-1">Delivery guarantees <a class="header-anchor" href="#delivery-guarantees" aria-label="Permalink to &quot;Delivery guarantees&quot;">​</a></h2><p><code>notification_outbox</code> is canonical delivery state. Each row has a unique idempotency key and moves through <code>pending</code>, <code>sending</code>, then <code>sent</code>, <code>failed</code>, <code>suppressed</code> or <code>cancelled</code> (with transient edit states for recovery updates). The worker claims one due row transactionally, stores Telegram&#39;s <code>message_id</code>, and retries transient failures with bounded exponential backoff. Stored text and reply markup pass through centralized redaction.</p><p>The External Sentinel remains independent and sends directly to Telegram so it can report failure of Homelab Console itself.</p><h2 id="presentation-policy" tabindex="-1">Presentation policy <a class="header-anchor" href="#presentation-policy" aria-label="Permalink to &quot;Presentation policy&quot;">​</a></h2><p>Automatic Telegram notifications use US English, including notifications about tasks, approvals, Luna, and the External Sentinel. User-supplied content and historical records embedded in a notification are not translated; normal redaction, aggregation, and length limits still apply.</p><h2 id="mcp-boundary" tabindex="-1">MCP boundary <a class="header-anchor" href="#mcp-boundary" aria-label="Permalink to &quot;MCP boundary&quot;">​</a></h2><p>MCP agents produce findings and task state through the existing execution core and task control plane. They cannot send, retry or suppress notifications. Dynamic read-only tools expose <code>notifications.status</code> and <code>notifications.outbox.list</code>; the latter omits message text and credentials.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOTIFICATION_OUTBOX_ENABLED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOTIFICATION_WORKER_INTERVAL_SECONDS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOTIFICATION_WARNING_DEBOUNCE_SECONDS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=900</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOTIFICATION_COOLDOWN_SECONDS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=7200</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOTIFICATION_CRITICAL_DEBOUNCE_SECONDS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=120</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOTIFICATION_CRITICAL_COOLDOWN_SECONDS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1800</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOTIFICATION_AGGREGATION_WINDOW_SECONDS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=120</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOTIFICATION_MAX_ATTEMPTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Keep warning debounce longer than one normal watcher interval. With the default 600-second watcher cadence and 900-second debounce, a one-sample flap is observed and audited but the next clean run cancels delivery before it can reach Telegram.</p>`,15)])])}const g=a(t,[["render",r]]);export{u as __pageData,g as default};
